import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import LinkButton from 'flarum/common/components/LinkButton';
import UserPage from 'flarum/forum/components/UserPage';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import { registerModels } from '../common/models';
import registerWidgets from './widgets';
import { t } from './util';
app.initializers.add('ernestdefoe-curio', () => {
  registerModels(app);

  // Pages load on first visit, never with every forum page.
  app.routes['curio.browse'] = {
    path: '/collections',
    component: () => import(/* webpackChunkName: 'forum/components/BrowsePage', webpackMode: 'lazy-once' */ './components/BrowsePage')
  };
  app.routes['curio.collection'] = {
    path: '/collections/:id',
    component: () => import(/* webpackChunkName: 'forum/components/CollectionPage', webpackMode: 'lazy-once' */ './components/CollectionPage')
  };
  app.routes['user.curio'] = {
    path: '/u/:username/collections',
    component: () => import(/* webpackChunkName: 'forum/components/UserCollectionsPage', webpackMode: 'lazy-once' */ './components/UserCollectionsPage')
  };
  extend(UserPage.prototype, 'navItems', function (items) {
    if (!this.user || !app.forum.attribute('canViewCurio')) return;
    items.add('curio', m(LinkButton, {
      href: app.route('user.curio', {
        username: this.user.slug()
      }),
      icon: "fas fa-boxes-stacked"
    }, t('profile.nav')), 85);
  });
  extend(IndexSidebar.prototype, 'navItems', function (items) {
    if (!app.forum.attribute('canViewCurio')) return;
    items.add('curio', m(LinkButton, {
      href: app.route('curio.browse'),
      icon: "fas fa-boxes-stacked"
    }, t('browse.title')), 85);
  });
  registerWidgets();
});flarum.reg.addChunkModule('ernestdefoe-curio:forum/components/BrowsePage', '803', 'ernestdefoe-curio', 'forum/components/BrowsePage');
flarum.reg.addChunkModule('ernestdefoe-curio:forum/components/CollectionPage', '285', 'ernestdefoe-curio', 'forum/components/CollectionPage');
flarum.reg.addChunkModule('ernestdefoe-curio:forum/components/UserCollectionsPage', '279', 'ernestdefoe-curio', 'forum/components/UserCollectionsPage');
flarum.reg.addChunkModule('ernestdefoe-curio:forum/components/BrowsePage', '803', 'ernestdefoe-curio', 'forum/components/CollectionEditModal');
flarum.reg.addChunkModule('ernestdefoe-curio:forum/components/BrowsePage', '803', 'ernestdefoe-curio', 'forum/components/ItemEditModal');
flarum.reg.addChunkModule('ernestdefoe-curio:forum/components/BrowsePage', '803', 'ernestdefoe-curio', 'forum/scanner');
flarum.reg.addChunkModule('ernestdefoe-curio:forum/components/BrowsePage', '803', 'ernestdefoe-curio', 'forum/components/ItemModal');
flarum.reg.addChunkModule('ernestdefoe-curio:forum/components/BrowsePage', '803', 'ernestdefoe-curio', 'forum/components/bits');
flarum.reg.addChunkModule('ernestdefoe-curio:forum/components/CollectionPage', '285', 'ernestdefoe-curio', 'common/gridSort');