import app from 'flarum/forum/app';
import Avatar from 'flarum/common/components/Avatar';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { t } from './util';

/**
 * "Recently added" for the widget hosts a forum may run: Bespoke and
 * fof/forum-widgets-core. Neither is a build dependency; each is found at run
 * time, so the bundle is the same with both, one or none installed. The list
 * is fetched only when a widget is actually on the page.
 */
class RecentList {
  oninit(vnode) {
    this.items = null;
    const limit = Math.max(1, Math.min(12, Number(vnode.attrs.limit) || 6));
    app.store.find('curio-items', {
      filter: {
        status: 'owned'
      },
      include: 'collection.user',
      sort: '-createdAt',
      page: {
        limit
      }
    }).then(items => this.items = items).catch(() => this.items = []).finally(() => m.redraw());
  }
  view() {
    if (this.items === null) return m(LoadingIndicator, {
      size: "small",
      display: "block"
    });
    if (!this.items.length) return m("p", {
      className: "CurioWidget-empty"
    }, t('widget.empty'));
    return m("ul", {
      className: "CurioWidget-list"
    }, this.items.map(item => {
      const collection = item.collection();
      const user = collection?.user();
      return m("li", null, m("a", {
        href: collection ? app.route('curio.collection', {
          id: `${collection.id()}-${collection.slug()}`
        }) + `?item=${item.id()}` : '#'
      }, item.coverUrl() ? m("img", {
        src: item.coverUrl(),
        alt: "",
        loading: "lazy"
      }) : m("span", {
        className: "CurioWidget-blank"
      }), m("span", null, m("strong", null, item.displayTitle()), user ? m("small", null, m(Avatar, {
        user: user
      }), " ", user.displayName()) : null)));
    }));
  }
}
export default function registerWidgets() {
  const flarum = globalThis.flarum;
  if (!flarum || !flarum.extensions) return;
  if ('ernestdefoe-bespoke' in flarum.extensions) {
    globalThis.BespokeWidgetQueue = globalThis.BespokeWidgetQueue || [];
    globalThis.BespokeWidgetQueue.push({
      type: 'curio-recent',
      label: 'ernestdefoe-curio.forum.widget.label',
      icon: 'fas fa-boxes-stacked',
      zones: ['sidebar', 'above-list', 'below-list', 'footer'],
      schema: [{
        key: 'title',
        type: 'text',
        label: 'ernestdefoe-curio.forum.widget.field_title',
        default: ''
      }, {
        key: 'limit',
        type: 'number',
        label: 'ernestdefoe-curio.forum.widget.field_limit',
        default: 6
      }],
      component: {
        view(vnode) {
          const s = vnode.attrs.settings || {};
          return m("div", {
            className: "CurioWidget"
          }, m("h4", {
            className: "CurioWidget-title"
          }, s.title || t('widget.label')), m(RecentList, {
            limit: s.limit
          }));
        }
      }
    });
  }
  if ('fof-forum-widgets-core' in flarum.extensions) {
    const widgetsMod = flarum.reg?.get?.('fof-forum-widgets-core', 'common/extend/Widgets');
    const widgetMod = flarum.reg?.get?.('fof-forum-widgets-core', 'common/components/Widget');
    const Widgets = widgetsMod?.default ?? widgetsMod;
    const WidgetBase = widgetMod?.default ?? widgetMod;
    if (!Widgets || !WidgetBase) return;
    class CurioRecentWidget extends WidgetBase {
      className() {
        return 'CurioWidget CurioWidget--fof';
      }
      icon() {
        return 'fas fa-boxes-stacked';
      }
      title() {
        return t('widget.label');
      }
      content() {
        return m(RecentList, {
          limit: 6
        });
      }
    }
    new Widgets().add({
      key: 'curioRecent',
      component: CurioRecentWidget,
      isDisabled: false,
      isUnique: true,
      placement: 'end',
      position: 3
    }).extend(app, 'ernestdefoe-curio');
  }
}